func (d *Reference) Update(ctx context.Context, reference *database.Reference, opt ...ExecOption) error {
	if !reference.IsChanged() {
		return nil
	}

	execOpts := newExecOpt(opt...)
	var conn execConn
	if execOpts.tx != nil {
		conn = execOpts.tx
	} else {
		conn = d.conn
	}

	changedColumn := reference.ChangedColumn()
	cols := make([]string, len(changedColumn)+1)
	values := make([]any, len(changedColumn)+1)
	for i := range changedColumn {
		cols[i] = "`" + changedColumn[i].Name + "` = ?"
		values[i] = changedColumn[i].Value
	}
	cols[len(cols)-1] = "`updated_at` = ?"
	values[len(values)-1] = time.Now()

	query := fmt.Sprintf("UPDATE `reference` SET %s WHERE `repository_id` = ? AND `name` = ?", strings.Join(cols, ", "))
	res, err := conn.ExecContext(
		ctx,
		query,
		append(values, reference.RepositoryId, reference.Name)...,
	)
	if err != nil {
		return err
	}
	if n, err := res.RowsAffected(); err != nil {
		return err
	} else if n == 0 {
		return sql.ErrNoRows
	}

	reference.ResetMark()
	return nil
}

type whereCondition struct {
	sql  string
	args []any
}

func whereCond(sql string, args ...any) *whereCondition {
	return &whereCondition{sql: sql, args: args}
}

// whereIn returns the condition that column is one of values. If values is empty, the condition is always false.
func whereIn[T any](column string, values []T) *whereCondition {
	if len(values) == 0 {
		return &whereCondition{sql: "1 = 0"}
	}
	args := make([]any, len(values))
	for i, v := range values {
		args[i] = v
	}
	return &whereCondition{sql: column + " IN (" + strings.TrimSuffix(strings.Repeat("?, ", len(values)), ", ") + ")", args: args}
}

func whereAnd(conds ...*whereCondition) *whereCondition {
	return whereJoin("AND", conds)
}

func whereOr(conds ...*whereCondition) *whereCondition {
	return whereJoin("OR", conds)
}

func whereJoin(op string, conds []*whereCondition) *whereCondition {
	sqls := make([]string, len(conds))
	var args []any
	for i, c := range conds {
		sqls[i] = c.sql
		args = append(args, c.args...)
	}
	return &whereCondition{sql: "(" + strings.Join(sqls, " "+op+" ") + ")", args: args}
}
